from typing import Tuple

def calc(func, n: int) -> float:
    temp = 0
    for _ in range(n):
        a, b = func(n)
        temp = b / (a + temp)
        n -= 1
    a, b = func(0)
    return a + temp

def sqrt2(n: int) -> Tuple[float, float]:
    return (n > 0 and 2 or 1, 1)

def napier(n: int) -> Tuple[float, float]:
    return (n > 0 and n or 2, n > 1 and n - 1 or 1)

def pi(n: int) -> Tuple[float, float]:
    return (n > 0 and 6 or 3, (2 * n - 1) * (2 * n - 1))

if __name__ == "__main__":
    print(calc(sqrt2, 20))
    print(calc(napier, 15))
    print(calc(pi, 10000))

