import hashlib
import string
import multiprocessing
 
def matches(a, b):
	for i in range(32):
		if a[i]!= b[i]:
			return False
	return True
 
 
def StringHashToByteArray(s):
	hash = bytearray(32)
	for i in range(32):
		two = s[i * 2:i * 2 + 2]
		hash[i] = int(two, 16)
	return hash
 
def printResult(password, hash):
	sPass = str(password, 'utf-8')
	print(sPass, '=>', hash.hex())
 
def main():
	one = StringHashToByteArray("1115dd800feaacefdf481f1f9070374a2a81e27880f187396db67958b207cbad")
	two = StringHashToByteArray("3a7bd3e2360a3d29eea436fcfb7e44c735d117c42d1c1835420b6b9942dd4f1b")
	three = StringHashToByteArray("74e1bb62f8dabb8125a58852b63bdf6eaef667cb56ac7f7cdba6d7305c50a22f")
	for a in string.ascii_lowercase:
		password = bytearray(a, 'utf-8')
		for b in string.ascii_lowercase:
			password[1] = ord(b)
			for c in string.ascii_lowercase:
				password[2] = ord(c)
				for d in string.ascii_lowercase:
					password[3] = ord(d)
					for e in string.ascii_lowercase:
						password[4] = ord(e)
						hash = hashlib.sha256(password).digest()
						if matches(one, hash) or matches(two, hash) or matches(three, hash):
							printResult(password, hash)
 
if __name__ == '__main__':
	with multiprocessing.Pool(4) as p:
		p.map(main, range(4))

from enum import Enum
from typing import List, Tuple
 
class State(Enum):
    EMPTY = 0
    CONDUCTOR = 1
    ELECTRON_TAIL = 2
    ELECTRON_HEAD = 3
 
class WireWorld:
    def __init__(self, width: int, height: int):
        self.width = width
        self.height = height
        self.data = [State.EMPTY] * (width * height)
 
    def get(self, x: int, y: int) -> State:
        if x >= self.width or y >= self.height:
            return None
        return self.data[y * self.width + x]
 
    def set(self, x: int, y: int, state: State):
        self.data[y * self.width + x] = state
 
    def neighbors(self, x: int, y: int, f: callable) -> int:
        neighbors = [(x-1,y-1),(x-1,y),(x-1,y+1),(x,y-1),(x,y+1),(x+1,y-1),(x+1,y),(x+1,y+1)]
        return len(list(filter(f, [self.get(x, y) for (x, y) in neighbors])))
 
    def next(self):
        next_state = []
        for y in range(self.height):
            for x in range(self.width):
                e_count = self.neighbors(x, y, lambda e: e == State.ELECTRON_HEAD)
                next_state.append(self.get(x, y).next(e_count))
        self.data = next_state
 
    @staticmethod
    def from_str(s: str) -> 'WireWorld':
        s = s.strip()
        height = len(s.splitlines())
        width = max(len(line.rstrip()) for line in s.splitlines())
        world = WireWorld(width, height)
 
        for y, line in enumerate(s.splitlines()):
            for x, ch in enumerate(line.rstrip()):
                state = {
                    '.': State.CONDUCTOR,
                    't': State.ELECTRON_TAIL,
                    'H': State.ELECTRON_HEAD,
                }.get(ch, State.EMPTY)
                world.set(x, y, state)
        return world

