def degree(p):
    for d in range(len(p) - 1, -1, -1):
        if p[d]!= 0:
            return d
    return -1
 
def pld(nn, dd):
    if degree(dd) < 0:
        return
    nn = r + nn
    if degree(nn) >= degree(dd):
        q = [0] * (degree(nn) - degree(dd) + 1)
        while degree(nn) >= degree(dd):
            d = [0] * (degree(nn) + 1)
            d[degree(nn) - degree(dd):] = dd
            q[degree(nn) - degree(dd)] = nn[degree(nn)] / d[degree(d)]
            for i in range(len(d)):
                d[i] *= q[degree(nn) - degree(dd)]
                nn[i] -= d[i]
    return q, nn, True
 
