import sys
 
SMALL = [
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
    "nineteen",
]
 
TENS = [
    "PANIC", "PANIC", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
]
 
MAGNITUDE = [
    "PANIC", "thousand", "million", "billion", "trillion", "quadrillion", "quintillion",
]
 
def wordify(number):
    if number == 0:
        return "zero"
    if number < 0:
        return "negative " + wordify(-number)
    result = []
    while number != 0:
        if number < 20:
            result.append(SMALL[number])
            break
        elif number < 100:
            result.append(TENS[number // 10])
            number %= 10
            if number != 0:
                result.append("-")
        elif number < 1_000:
            result.append(SMALL[number // 100] + " hundred")
            number %= 100
            if number != 0:
                result.append(" and ")
        else:
            top = number
            magnitude = 0
            magnitude_pow = 1
            while top >= 1_000:
                top //= 1_000
                magnitude += 1
                magnitude_pow *= 1_000
            result.append(wordify(top))
            number %= magnitude_pow
            if number == 0:
                result.append(" " + MAGNITUDE[magnitude])
            elif number > 100:
                result.append(", " + MAGNITUDE[magnitude])
            else:
                result.append(" and " + MAGNITUDE[magnitude])
    return "".join(result)
 
for n in [12, 1048576, 9_000_000_000_000_000_000, -2, 0, 5_000_000_000_000_000_001, -555_555_555_555]:
    print(wordify(n))

