from itertools import count
from math import sqrt
 
def abundant_numbers(start=3):
    for n in count(start, 2):
        if sum(divisors(n)) > n:
            yield n
 
def divisors(n):
    for i in range(3, int(sqrt(n)) + 1, 2):
        if n % i == 0:
            yield i
            yield n // i
    yield 1
 
