class DivMod:
    def __init__(self, quotient, remainder):
        self.quotient = quotient
        self.remainder = remainder
 
def egyptianDivide(dividend, divisor):
    assert dividend >= 0 and divisor > 0
    if dividend < divisor:
        return DivMod(0, dividend)
    powersOfTwo = [1]
    doublings = [divisor]
    doubling = divisor
    while True:
        doubling *= 2
        if doubling > dividend:
            break
        powersOfTwo.append(powersOfTwo[-1] * 2)
        doublings.append(doubling)
    answer = 0
    accumulator = 0
    for i in range(len(doublings) - 1, -1, -1):
        if accumulator + doublings[i] <= dividend:
            accumulator += doublings[i]
            answer += powersOfTwo[i]
            if accumulator == dividend:
                break
    return DivMod(answer, dividend - accumulator)
 
dividend = 580
divisor = 34
quotient, remainder = egyptianDivide(dividend, divisor)
print(f"{dividend} divided by {divisor} is {quotient} with remainder {remainder}")

