DIRS = [(0, -1), (-1, 0), (0, 1), (1, 0)]
 
def print_result(v):
    for row in v:
        print('[', end='')
        print(*row, sep=', ', end='')
        print(']')
 
def cut_rectangle(w, h):
    if w % 2 == 1 and h % 2 == 1:
        return
 
    grid = [[0] * w for _ in range(h)]
    stack = []
 
    half = (w * h) // 2
    bits = 2 ** half - 1
 
    for bits in range(bits, 0, -2):
        for i in range(half):
            r = i // w
            c = i % w
            grid[r][c] = (bits & (1 << i))!= 0
            grid[h - r - 1][w - c - 1] = 1 - grid[r][c]
 
        stack.append(0)
        grid[0][0] = 2
        count = 1
        while stack:
            pos = stack.pop()
 
            r = pos // w
            c = pos % w
            for dir in DIRS:
                next_r = r + dir[0]
                next_c = c + dir[1]
 
                if 0 <= next_r < h and 0 <= next_c < w:
                    if grid[next_r][next_c] == 1:
                        stack.append(next_r * w + next_c)
                        grid[next_r][next_c] = 2
                        count += 1
 
        if count == half:
            print_result(grid)
            print()
 
if __name__ == '__main__':
