def isPrime(x):
	if x < 2:
		return False
	if x == 2:
		return True
	if x % 2 == 0:
		return False
 
	for i in range(3, int(x**0.5)+1, 2):
		if x % i == 0:
			return False
 
	return True
 
 
def isEmirp(x):
	xString = str(x)
	if len(xString) == 1:
		return False
	if xString.startswith('2') or xString.startswith('4') or xString.startswith('5') or xString.startswith('6') or xString.startswith('8') or xString.endswith('2') or xString.endswith('4') or xString.endswith('5') or xString.endswith('6') or xString.endswith('8'):
		return False
	xR = int(xString[::-1])
	if xR == x:
		return False
	return isPrime(x) and isPrime(xR)
 
 
