import numpy as np
from PIL import Image
import matplotlib.pyplot as plt
import matplotlib.image as mpimg
import queue
 
def ColorMatch(a, b):
    return (a & 0xffffff) == (b & 0xffffff)
 
def FloodFill(bmp, pt, targetColor, replacementColor):
    q = queue.Queue()
    q.put(pt)
    while not q.empty():
        n = q.get()
        if not ColorMatch(bmp[n[0], n[1]], targetColor):
            continue
        w = n
        e = [n[0] + 1, n[1]]
        while (w[0] >= 0) and ColorMatch(bmp[w[0], w[1]], targetColor):
            bmp[w[0], w[1]] = replacementColor
            if (w[1] > 0) and ColorMatch(bmp[w[0], w[1] - 1], targetColor):
                q.put([w[0], w[1] - 1])
            if (w[1] < bmp.shape[1] - 1) and ColorMatch(bmp[w[0], w[1] + 1], targetColor):
                q.put([w[0], w[1] + 1])
            w[0] -= 1
        while (e[0] <= bmp.shape[0] - 1) and ColorMatch(bmp[e[0], e[1]], targetColor):
            bmp[e[0], e[1]] = replacementColor
            if (e[1] > 0) and ColorMatch(bmp[e[0], e[1] - 1], targetColor):
                q.put([e[0], e[1] - 1])
            if (e[1] < bmp.shape[1] - 1) and ColorMatch(bmp[e[0], e[1] + 1], targetColor):
                q.put([e[0], e[1] + 1])
            e[0] += 1
 
