from rug import Integer
 
def jacobsthal_numbers():
    for x in range(100):
        yield ((Integer(1) << x) - (1 if x % 2 == 0 else -1)) // 3
 
def jacobsthal_lucas_numbers():
    for x in range(100):
        yield (Integer(1) << x) + (1 if x % 2 == 0 else -1)
 
def jacobsthal_oblong_numbers():
    jn = jacobsthal_numbers()
    n0 = next(jn)
    for n1 in jn:
        yield n0 * n1
        n0 = n1
 
def jacobsthal_primes():
    for n in jacobsthal_numbers():
        if n.is_probably_prime(30):
            yield n
 
if __name__ == "__main__":
    print("First 30 Jacobsthal Numbers:")
    for i, n in enumerate(jacobsthal_numbers()):
        print(f"{n:9}", end=" " if (i + 1) % 5 else "\n")
    print("\nFirst 30 Jacobsthal-Lucas Numbers:")
    for i, n in enumerate(jacobsthal_lucas_numbers()):
        print(f"{n:9}", end=" " if (i + 1) % 5 else "\n")
    print("\nFirst 20 Jacobsthal oblong Numbers:")
    for i, n in enumerate(jacobsthal_oblong_numbers()):
        print(f"{n:11}", end=" " if (i + 1) % 5 else "\n")
    print("\nFirst 20 Jacobsthal primes:")
    for n in jacobsthal_primes():
        print(n)

import math

def Sort(old):
    i = 0
    j = 0
    tmp = [0] * len(old)
    for shift in range(31, -1, -1):
        j = 0
        for i in range(0, len(old)):
            move = (old[i] << shift) >= 0
            if shift == 0 and not move:
                old[i-j] = old[i]
            elif move:
                old[i-j] = old[i]
            else:
                tmp[j] = old[i]
                j += 1
        for i in range(0, j):
            old[len(old)-j+i] = tmp[i]

