class SelectionSort(object):
    def sort(self, list):
        k = 0
        temp = 0
 
        for i in range(0, len(list)):
            k = i
            for j in range(i + 1, len(list)):
                if list[j] < list[k]:
                    k = j
            temp = list[i]
            list[i] = list[k]
            list[k] = temp
 
        return list

import math
 
def sieve(limit):
    primes = [2]
    c = [False] * (limit + 1) # composite = True
    # no need to process even numbers > 2
    p = 3
    while True:
        p2 = p * p
        if p2 > limit:
            break
        for i in range(p2, limit + 1, 2 * p):
            c[i] = True
        while True:
            p += 2
            if not c[p]:
                break
    for i in range(3, limit + 1, 2):
        if not c[i]:
            primes.append(i)
    return primes
 
def square_free(from_, to):
    limit = int(math.sqrt(to))
    primes = sieve(limit)
    results = []
 
    for i in range(from_, to + 1):
        for p in primes:
            p2 = p * p
            if p2 > i:
                break
            if i % p2 == 0:
                continue
        results.append(i)
    return results
 
