from gmpy2 import mpfr, sqrt, add, div, mul, sub, mpz
 
def agm(in1, in2):
	out1 = add(in1, in2)
	out1 = div(out1, mpz(2))
	out2 = mul(in1, in2)
	out2 = sqrt(out2)
	return out1, out2
 
