def padovanN(n, t):
    if n < 2 or t < 3:
        ones = [1] * t
        return ones
    p = padovanN(n-1, t)
    for i in range(n, t):
        p[i] = 0
        for j in range(i-2, i-n-1, -1):
            p[i] += p[j]
    return p
 
t = 15
print("First", t, "terms of the Padovan n-step number sequences:")
for n in range(2, 9):
    print(n, ":", padovanN(n, t))

