import sys
import os
 
def main():
    if len(sys.argv) < 2:
        print("Usage: {} [path] (--debug)".format(sys.argv[0]))
        return
 
    src = []
    try:
        with open(sys.argv[1], 'r') as f:
            src = list(f.read())
    except Exception as e:
        print("Error opening '{}': {}".format(sys.argv[1], e))
        return
 
    # Launch options
    debug = "--debug" in sys.argv
 
    # One pass to find bracket pairs.
    brackets = {}
    scope_stack = []
    for idx, ch in enumerate(src):
        if ch == '[':
            scope_stack.append(idx)
        elif ch == ']':
            brackets[scope_stack.pop()] = idx
 
    pc = 0  # Program counter
    mem = [0] * 5000  # Program cemory
    ptr = 0  # Pointer
    stack = []  # Bracket stack
 
    while pc < len(src):
        val = mem[ptr]
 
        if debug:
            print("(BFDB) PC: {:04} \tPTR: {:04} \t$PTR: {:03} \tSTACK_DEPTH: {} \tSYMBOL: {}".format(pc, ptr, val, len(stack), src[pc]))
 
        ONE = 1
        if src[pc] == '>':
            ptr += 1
        elif src[pc] == '<':
            ptr -= 1
 
        elif src[pc] == '+':
            mem[ptr] = (mem[ptr] + ONE) % 256
        elif src[pc] == '-':
            mem[ptr] = (mem[ptr] - ONE) % 256
 
        elif src[pc] == '[':
            if val == 0:
                pc = brackets[pc]
            else:
                stack.append(pc)
        elif src[pc] == ']':
            matching_bracket = stack.pop()
            if val!= 0:
                pc = matching_bracket - 1
 
        elif src[pc] == '.':
            if debug:
                print("(BFDB) STDOUT: '{}'".format(chr(val)))  # Intercept output
            else:
                sys.stdout.write(chr(val))
        elif src[pc] == ',':
            mem[ptr] = ord(sys.stdin.read(1))
 
        pc += 1
 
if __name__ == "__main__":
    main()

import math
 
def factorial(number):
    accumulator = 1
 
    for factor in range(1, number + 1):
        accumulator *= factor
 
    return accumulator
 
def left_factorial(n):
    result = 0
 
    for i in range(0, n):
        result += factorial(i)
 
    return result
 
for i in range(0, 11):
    print("!{0} = {1}".format(i, left_factorial(i)))
 
for j in range(20, 111, 10):
    print("!{0} = {1}".format(j, left_factorial(j)))
 
for k in range(1000, 10001, 1000):
    print("!{0} has {1} digits".format(k, len(str(left_factorial(k)))))

