def queenPuzzle(rows, columns):
    if rows <= 0:
        return [[]]
    else:
        return addQueen(rows - 1, columns)
 
def addQueen(newRow, columns, prevSolution):
    newSolutions = []
    prev = queenPuzzle(newRow, columns)
    for i in range(len(prev)):
        solution = prev[i]
        for newColumn in range(columns):
            if not hasConflict(newRow, newColumn, solution):
                newSolutions.append(solution + [newColumn])
    return newSolutions
 
def hasConflict(newRow, newColumn, solution):
    for i in range(newRow):
        if solution[i] == newColumn or \
           solution[i] + i == newColumn + newRow or \
           solution[i] - i == newColumn - newRow:
            return True
    return False
 
