import math
import numpy as np

def count_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i == n / i:
                count += 1
            else:
                count += 2
    return count

def main():
    max = 15
    seq = np.zeros(max, dtype=int)
    print("The first %d terms of the sequence are:" % max)
    for i in range(1, max + 1):
        k = count_divisors(i)
        if k <= max and seq[k - 1] == 0:
            seq[k - 1] = i
    print(seq)

if __name__ == "__main__":
    main()

from itertools import count
 
def squares_gen():
    for n in count():
        yield n * n
 
def cubes_gen():
    for n in count():
        yield n * n * n
 
def generator_exponential(source, filter):
    s = source()
    f = filter()
 
    while True:
        if s!= f:
            yield s
            s = source()
            f = filter()
 
        while s > f:
            f = filter()
 
if __name__ == '__main__':
    for n in generator_exponential(squares_gen, cubes_gen):
        print(n, end=' ')

