MAX = 10_000_000 + 1000
primes = [True] * MAX

def sieve():
    for i in range(2, MAX):
        primes[i] = True
    for i in range(2, MAX):
        if primes[i]:
            for j in range(2*i, MAX, i):
                primes[j] = False

def strong_primes_below(max_prime):
    prior_prime = 2
    current_prime = 3
    count = 0
    while current_prime < max_prime:
        next_prime = get_next_prime(current_prime)
        if current_prime * 2 > prior_prime + next_prime:
            count += 1
        prior_prime = current_prime
        current_prime = next_prime
    return count

def display_strong_primes(max_count):
    prior_prime = 2
    current_prime = 3
    count = 0
    while count < max_count:
        next_prime = get_next_prime(current_prime)
        if current_prime * 2 > prior_prime + next_prime:
            count += 1
            print(current_prime, end=' ')
        prior_prime = current_prime
        current_prime = next_prime
    print()

def get_next_prime(current_prime):
    next_prime = current_prime + 2
    while not primes[next_prime]:
        next_prime += 2
    return next_prime

def weak_primes_below(max_prime):
    prior_prime = 2
    current_prime = 3
    count = 0
    while current_prime < max_prime:
        next_prime = get_next_prime(current_prime)
        if current_prime * 2 < prior_prime + next_prime:
            count += 1
        prior_prime = current_prime
        current_prime = next_prime
    return count

def display_weak_primes(max_count):
    prior_prime = 2
    current_prime = 3
    count = 0
    while count < max_count:
        next_prime = get_next_prime(current_prime)
        if current_prime * 2 < prior_prime + next_prime:
            count += 1
            print(current_prime, end=' ')
        prior_prime = current_prime
        current_prime = next_prime
    print()

