import math
 
class Node:
    def __init__(self, v, fixed_):
        self.v = v
        self.fixed = fixed_
 
def set_boundary(m):
    m[1][1].v = 1.0
    m[1][1].fixed = 1
 
    m[6][7].v = -1.0
    m[6][7].fixed = -1
 
def calcuate_difference(m, d, w, h):
    total = 0.0
    for i in range(h):
        for j in range(w):
            v = 0.0
            n = 0
            if i > 0:
                v += m[i - 1][j].v
                n += 1
            if j > 0:
                v += m[i][j - 1].v
                n += 1
            if i + 1 < h:
                v += m[i + 1][j].v
                n += 1
            if j + 1 < w:
                v += m[i][j + 1].v
                n += 1
            v = m[i][j].v - v / n
            d[i][j].v = v
            if m[i][j].fixed == 0:
                total += v * v
    return total
 
def iter(m, w, h):
    d = [[Node(0.0, 0) for j in range(w)] for i in range(h)]
 
    diff = 1e10
 
    while diff > 1e-24:
        set_boundary(m)
        diff = calcuate_difference(m, d, w, h)
        for i in range(h):
            for j in range(w):
                m[i][j].v -= d[i][j].v
 
    curr = [0.0, 0.0, 0.0]
    for i in range(h):
        for j in range(w):
            k = 0
            if i!= 0: k += 1
            if j!= 0: k += 1
            if i < h - 1: k += 1
            if j < w - 1: k += 1
            curr[m[i][j].fixed + 1] += d[i][j].v * k
 
    return (curr[2] - curr[0]) / 2.0
 
