class Latin:
    def __init__(self, size=3):
        self.size = size
        self.mst = [i + 1 for i in range(self.size)]
        self.square = [[0 for i in range(self.size)] for j in range(self.size)]
        if self.create(0, 0):
            print(self.square)
 
    def create(self, c, r):
        d = self.mst[:]
        s = 0
        while True:
            while True:
                s = d.pop(random.randint(0, len(d) - 1))
                if not s:
                    return False
                if not self.check(s, c, r):
                    break
            self.square[c][r] = s
            if c + 1 >= self.size:
                c = 0
                if r + 1 >= self.size:
                    return True
                r += 1
            else:
                c += 1
            if self.create(c, r):
                return True
            if c - 1 < 0:
                c = self.size - 1
                if r - 1 < 0:
                    return False
                r -= 1
            else:
                c -= 1
 
    def check(self, d, c, r):
        for a in range(self.size):
            if c - a > -1:
                if self.square[c - a][r] == d:
                    return True
            if r - a > -1:
                if self.square[c][r - a] == d:
                    return True
        return False
 
