def jaro(str1, str2):
    if len(str1) == 0 and len(str2) == 0:
        return 1
    if len(str1) == 0 or len(str2) == 0:
        return 0
    match_distance = len(str1)
    if len(str2) > match_distance:
        match_distance = len(str2)
    match_distance = match_distance/2 - 1
    str1_matches = [False] * len(str1)
    str2_matches = [False] * len(str2)
    matches = 0.
    transpositions = 0.
    for i in range(len(str1)):
        start = i - match_distance
        if start < 0:
            start = 0
        end = i + match_distance + 1
        if end > len(str2):
            end = len(str2)
        for k in range(start, end):
            if str2_matches[k]:
                continue
            if str1[i]!= str2[k]:
                continue
            str1_matches[i] = True
            str2_matches[k] = True
            matches += 1
            break
    if matches == 0:
        return 0
    k = 0
    for i in range(len(str1)):
        if not str1_matches[i]:
            continue
        while not str2_matches[k]:
            k += 1
        if str1[i]!= str2[k]:
            transpositions += 1
        k += 1
    transpositions /= 2
    return (matches/float(len(str1)) +
        matches/float(len(str2)) +
        (matches-transpositions)/matches) / 3
 
if __name__ == '__main__':
    print(jaro("MARTHA", "MARHTA"))
    print(jaro("DIXON", "DICKSONX"))
    print(jaro("JELLYFISH", "SMELLYFISH"))

class LogicPuzzle:
    def __init__(self):
        self.S = [False] * 13
        self.Count = 0

    def check2(self):
        count = 0
        for k in range(7, 13):
            if self.S[k]:
                count += 1
        return self.S[2] == (count == 3)

    def check3(self):
        count = 0
        for k in range(2, 13, 2):
            if self.S[k]:
                count += 1
        return self.S[3] == (count == 2)

    def check4(self):
        return self.S[4] == (not self.S[5] or self.S[6] and self.S[7])

    def check5(self):
        return self.S[5] == (not self.S[2] and not self.S[3] and not self.S[4])

    def check6(self):
        count = 0
        for k in range(1, 12, 2):
            if self.S[k]:
                count += 1
        return self.S[6] == (count == 4)

    def check7(self):
        return self.S[7] == ((self.S[2] or self.S[3]) and not (self.S[2] and self.S[3]))

    def check8(self):
        return self.S[8] == (not self.S[7] or self.S[5] and self.S[6])

    def check9(self):
        count = 0
        for k in range(1, 7):
            if self.S[k]:
                count += 1
        return self.S[9] == (count == 3)

    def check10(self):
        return self.S[10] == (self.S[11] and self.S[12])

    def check11(self):
        count = 0
        for k in range(7, 10):
            if self.S[k]:
                count += 1
        return self.S[11] == (count == 1)

    def check12(self):
        count = 0
        for k in range(1, 12):
            if self.S[k]:
                count += 1
        return self.S[12] == (count == 4)

    def check(self):
        if self.check2() and self.check3() and self.check4() and self.check5() and self.check6() and self.check7() and self.check8() and self.check9() and self.check10() and self.check11() and self.check12():
            for k in range(1, 13):
                if self.S[k]:
                    print(k, end=' ')
            print()
            self.Count += 1

    def recurseAll(self, k):
        if k == 13:
            self.check()
        else:
            self.S[k] = False
            self.recurseAll(k + 1)
            self.S[k] = True
            self.recurseAll(k + 1)

    def main(self):
        self.S[1] = True
        self.recurseAll(2)
        print()
        print(self.Count, "Solutions found.")

