Sedol_char = "0123456789BCDFGHJKLMNPQRSTVWXYZ"
Sedolweight = [1,3,1,7,3,9]
 
def char2value(c):
    if c not in Sedol_char:
        raise ValueError("Invalid char %s" % c)
    return int(c, 36)
 
def checksum(sedol):
    if len(sedol)!= len(Sedolweight):
        raise ValueError("Invalid length")
    sum = 0
    for ch, weight in zip(sedol, Sedolweight):
        sum += char2value(ch) * weight
    return ((10 - (sum % 10)) % 10)
 
