import ctypes
import sys
 
class DATA(ctypes.c_int):
    pass
 
class queue_t(ctypes.Structure):
    _fields_ = [("buf", ctypes.POINTER(DATA)),
                ("head", ctypes.c_size_t),
                ("tail", ctypes.c_size_t),
                ("alloc", ctypes.c_size_t)]
 
class queue(ctypes.Structure):
    _fields_ = [("contents", ctypes.POINTER(queue_t))]
 
def q_new():
    q = queue()
    q.contents = ctypes.cast(ctypes.create_string_buffer(ctypes.sizeof(queue_t)), ctypes.POINTER(queue_t)).contents
    q.contents.buf = ctypes.cast(ctypes.create_string_buffer(ctypes.sizeof(DATA) * 4), ctypes.POINTER(DATA)).contents
    q.contents.head = q.contents.tail = 0
    q.contents.alloc = 4
    return q
 
def empty(q):
    return q.contents.tail == q.contents.head
 
def enqueue(q, n):
    if q.contents.tail >= q.contents.alloc:
        q.contents.tail = 0
    q.contents.buf[q.contents.tail] = n
    q.contents.tail += 1
 
    # Fixed bug where it failed to resizes
    if q.contents.tail == q.contents.alloc:  # needs more room
        q.contents.buf = ctypes.cast(ctypes.create_string_buffer(ctypes.sizeof(DATA) * q.contents.alloc * 2), ctypes.POINTER(DATA)).contents
        if q.contents.head:
            ctypes.memmove(ctypes.addressof(q.contents.buf[q.contents.head + q.contents.alloc]), ctypes.addressof(q.contents.buf[q.contents.head]), ctypes.sizeof(DATA) * (q.contents.alloc - q.contents.head))
            q.contents.head += q.contents.alloc
        else:
            q.contents.tail = q.contents.alloc
        q.contents.alloc *= 2
 
def dequeue(q, n):
    if q.contents.head == q.contents.tail:
        return 0
    n[0] = q.contents.buf[q.contents.head]
    q.contents.head += 1
    if q.contents.head >= q.contents.alloc:  # reduce allocated storage no longer needed
        q.contents.head = 0
        if q.contents.alloc >= 512 and q.contents.tail < q.contents.alloc / 2:
            q.contents.buf = ctypes.cast(ctypes.create_string_buffer(ctypes.sizeof(DATA) * (q.contents.alloc/2)), ctypes.POINTER(DATA)).contents
            q.contents.alloc /= 2
    return 1
 
if __name__ == "__main__":
    q = q_new()
    for i in range(100):
        enqueue(q, i)
    for i in range(100):
        n = DATA()
        if dequeue(q, n):
            print n.value

