def gnomesort(lst):
    i, j = 1, 2
    while i < len(lst):
        if lst[i-1] <= lst[i]:
            i, j = j, j+1
        else:
            lst[i-1], lst[i] = lst[i], lst[i-1]
            i -= 1
            if i == 0:
                i, j = j, j+1
    return lst

