import math
 
def mult(n, base):
	mult = 1
	while mult > 0 and n > 0:
		mult *= n % base
		n //= base
	return mult
 
def mult_digital_root(n, base):
	mp = 0
	while n >= base:
		n = mult(n, base)
		mp += 1
	return mp, n
 
def main():
