def bit_count(n):
    count = 0
    while n > 0:
        n >>= 1
        count += 1
    return count
 
def mod_pow(p, n):
    square = 1
    bits = bit_count(p)
    while bits > 0:
        square = square * square
        bits -= 1
        if (p & (1 << bits))!= 0:
            square <<= 1
        square %= n
    return square
 
def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    if n % 3 == 0:
        return n == 3
    p = 5
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
        if n % p == 0:
            return False
        p += 4
    return True
 
def find_mersenne_factor(p):
    k = 0
    while True:
        k += 1
        q = 2 * k * p + 1
        if q % 8 == 1 or q % 8 == 7:
            if mod_pow(p, q) == 1 and is_prime(p):
                return q
 
