class LinkedList:
    class Node:
        def __init__(self, data, prev=None, next=None):
            self.data = data
            self.prev = prev
            self.next = next
 
        def __str__(self):
            sb = str(self.data)
            node = self.next
            while node:
                sb += " -> " + str(node.data)
                node = node.next
            return sb
 
    def __init__(self):
        self.first = None
        self.last = None
 
    def addFirst(self, value):
        if self.first is None:
            self.first = self.Node(value)
            self.last = self.first
        else:
            node = self.first
            self.first = self.Node(value, None, node)
            node.prev = self.first
 
    def addLast(self, value):
        if self.last is None:
            self.last = self.Node(value)
            self.first = self.last
        else:
            node = self.last
            self.last = self.Node(value, node, None)
            node.next = self.last
 
    def insert(self, after, value):
        if after is None:
            self.addFirst(value)
        elif after == self.last:
            self.addLast(value)
        else:
            next = after.next
            new = self.Node(value, after, next)
            after.next = new
            if next: next.prev = new
 
    def __str__(self):
        return str(self.first)
 
    def firstToLast(self):
        return str(self.first)
 
    def lastToFirst(self):
        if self.last is None: return ""
        sb = str(self.last)
        node = self.last.prev
        while node:
            sb += " -> " + str(node.data)
            node = node.prev
        return sb
 
if __name__ == "__main__":
    ll = LinkedList()
    ll.addFirst(1)
    ll.addLast(4)
    ll.insert(ll.first, 2)
    ll.insert(ll.last.prev, 3)
    print("First to last : {}".format(ll.firstToLast()))
    print("Last to first : {}".format(ll.lastToFirst()))

