def rot13(s):
    lcalph = "abcdefghijklmnopqrstuvwxyz"
    ucalph = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = ""
    for c in s:
        if c in lcalph:
            result += lcalph[(lcalph.find(c) + 13) % 26]
        elif c in ucalph:
            result += ucalph[(ucalph.find(c) + 13) % 26]
        else:
            result += c
    return result
 
def rot13_stream(is):
    for line in is:
        print rot13(line)
 
