LIMIT = 1_000_000
 
def self_ref_seq(s):
    return ''.join(str(s.count(d)) + d for d in '9876543210' if d in s)
 
def permute(input):
    if len(input) == 1:
        return [input]
    perms = []
    to_insert = input[0]
    for perm in permute(input[1:]):
        for i in range(len(perm) + 1):
            new_perm = perm[:i] + [to_insert] + perm[i:]
            perms.append(new_perm)
    return perms
 
def main():
    sieve = [0] * LIMIT
    elements = []
    for n in range(1, LIMIT):
        if sieve[n] > 0:
            continue
        elements.clear()
        next = str(n)
        elements.append(next)
        while True:
            next = self_ref_seq(next)
            if next in elements:
                size = len(elements)
                sieve[n] = size
                if n > 9:
                    perms = permute(list(str(n)))
                    for perm in perms:
                        if perm[0] == '0':
                            continue
                        k = int(''.join(perm))
                        sieve[k] = size
                break
            elements.append(next)
    max_iterations = max(sieve)
    for n in range(1, LIMIT):
        if sieve[n] < max_iterations:
            continue
        print(f'{n} -> Iterations = {max_iterations}')
        next = str(n)
        for i in range(1, max_iterations + 1):
            print(next)
            next = self_ref_seq(next)
        print()
 
