def s_of_n_creator(n):
    s = []
    m = n
    def s_of_n(item):
        nonlocal s, m
        if len(s) < n:
            s.append(item)
        else:
            m += 1
            if random.randint(0, m) < n:
                s[random.randint(0, n - 1)] = item
        return s
    return s_of_n
 
