from typing import List
 
def pascal_upper(n: int) -> List[List[int]]:
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i > j:
                matrix[i][j] = 0
            elif i == j or i == 0:
                matrix[i][j] = 1
            else:
                matrix[i][j] = matrix[i - 1][j - 1] + matrix[i][j - 1]
    return matrix
 
def pascal_lower(n: int) -> List[List[int]]:
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i < j:
                matrix[i][j] = 0
            elif i == j or j == 0:
                matrix[i][j] = 1
            else:
                matrix[i][j] = matrix[i - 1][j - 1] + matrix[i - 1][j]
    return matrix
 
def pascal_symmetric(n: int) -> List[List[int]]:
    matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == 0 or j == 0:
                matrix[i][j] = 1
            else:
                matrix[i][j] = matrix[i][j - 1] + matrix[i - 1][j]
    return matrix
 
def print_matrix(matrix: List[List[int]]):
    for row in matrix:
        for i in row:
            print(f" {i}", end="")
        print()
 
if __name__ == "__main__":
    print("PASCAL UPPER MATRIX")
    print_matrix(pascal_upper(5))
    print("PASCAL LOWER MATRIX")
    print_matrix(pascal_lower(5))
    print("PASCAL SYMMETRIC MATRIX")
    print_matrix(pascal_symmetric(5))

import numpy as np
 
def rref(m):
    lead = 0
    rowCount = len(m)
    columnCount = len(m[0])
    for r in range(rowCount):
        if lead >= columnCount:
            return
        i = r
        while m[i][lead] == 0:
            i += 1
            if rowCount == i:
                i = r
                lead += 1
                if columnCount == lead:
                    return
        m[i], m[r] = m[r], m[i]
        f = 1 / m[r][lead]
        for j in range(columnCount):
            m[r][j] *= f
        for i in range(rowCount):
            if i!= r:
                f = m[i][lead]
                for j in range(columnCount):
                    m[i][j] -= f * m[r][j]
        lead += 1
 
