import random
 
def shuffle(v):
    for i in range(len(v)-1, 0, -1):
        j = random.randint(0, i)
        v[i], v[j] = v[j], v[i]
    return v
 
def isSorted(v):
    for i in range(1, len(v)):
        if v[i-1] > v[i]:
            return False
    return True
 
def bogosort(v):
    sorted = False
    while not sorted:
        v = shuffle(v)
        sorted = isSorted(v)
    return v

import heapq
import itertools

class CubeSum(object):
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.value = x*x*x + y*y*y

    def __str__(self):
        return "%4d^3 + %4d^3" % (self.x, self.y)

    def __lt__(self, other):
        return self.value < other.value

class SumIterator(object):
    def __init__(self):
        self.pq = []
        self.n = 0

    def __iter__(self):
        return self

    def next(self):
        while len(self.pq) == 0 or self.pq[0].value >= self.n*self.n*self.n:
            heapq.heappush(self.pq, CubeSum(self.n+1, 1))
            self.n += 1

        s = heapq.heappop(self.pq)
        if s.x > s.y + 1:
            heapq.heappush(self.pq, CubeSum(s.x, s.y+1))

        return s

class TaxiIterator(object):
    def __init__(self):
        self.sum_iterator = SumIterator()
        self.last = self.sum_iterator.next()

    def __iter__(self):
        return self

    def next(self):
        s = self.sum_iterator.next()
        train = []

        while s.value!= self.last.value:
            self.last = s
            s = self.sum_iterator.next()

        train.append(self.last)

        while s.value == self.last.value:
            train.append(s)
            s = self.sum_iterator.next()

        self.last = s

        return train

