import io
 
class BitReader:
    def __init__(self, stream):
        self.stream = stream
        self.readData = 0
        self.startPosition = 0
        self.endPosition = 0
 
    @property
    def InBuffer(self):
        return self.endPosition - self.startPosition
 
    @property
    def BaseStream(self):
        return self.stream
 
    def EnsureData(self, bitCount):
        readBits = bitCount - self.InBuffer
        while readBits > 0:
            b = self.BaseStream.read(1)
 
            if b < 0:
                raise Exception("Unexpected end of stream")
 
            self.readData |= b << self.endPosition
            self.endPosition += 8
            readBits -= 8
 
    def ReadBit(self):
        return self.Read(1) > 0
 
    def Read(self, bitCount):
        self.EnsureData(bitCount)
 
        result = (self.readData >> self.startPosition) & ((1 << bitCount) - 1)
        self.startPosition += bitCount
        if self.endPosition == self.startPosition:
            self.endPosition = self.startPosition = 0
            self.readData = 0
        elif self.startPosition >= 8:
            self.readData >>= self.startPosition
            self.endPosition -= self.startPosition
            self.startPosition = 0
 
        return result
 
    def Align(self):
        self.endPosition = self.startPosition = 0
        self.readData = 0
 
class BitWriter:
    def __init__(self, stream):
        self.stream = stream
        self.data = 0
        self.dataLength = 0
 
    @property
    def BaseStream(self):
        return self.stream
 
    @property
    def BitsToAligment(self):
        return (32 - self.dataLength) % 8
 
    def WriteBit(self, value):
        self.Write(1 if value else 0, 1)
 
    def Write(self, value, length):
        currentData = self.data | (value << self.dataLength)
        currentLength = self.dataLength + length
        while currentLength >= 8:
            self.BaseStream.write(currentData)
            currentData >>= 8
            currentLength -= 8
        self.data = currentData
        self.dataLength = currentLength
 
    def Align(self):
        if self.dataLength > 0:
            self.BaseStream.write(self.data)
 
            self.data = 0
            self.dataLength = 0
 
