import re
 
def commatize(s, start=0, step=3, ins=','):
    if start < 0 or start > len(s) or step < 1 or step > len(s):
        return
 
    m = re.search(r'([1-9][0-9]*)', s[start:])
    result = s[:start]
 
    if m:
        sb = m.group(1)[::-1]
        for i in range(step, len(sb), step):
            sb = sb[:i] + ins + sb[i:]
        m.expand(sb[::-1], result)
 
    print(m.appendTail(result))
 
