def totient(n):
    tot = n
    nn = n
    i = 2
    while i * i <= nn:
        if nn % i == 0:
            while nn % i == 0:
                nn //= i
            tot -= tot // i
        if i == 2:
            i = 1
        i += 2
    if nn > 1:
        tot -= tot // nn
    return tot
 
def main():
    print(" n  phi   prime")
    print("---------------")
    count = 0
    for n in range(1, 26):
        tot = totient(n)
        isPrime  = n - 1 == tot
        if isPrime:
            count += 1
        print(f"{n:2d}   {tot:2d}   {isPrime}")
    print("\nNumber of primes up to 25     =", count)
    for n in range(26, 100_000 + 1):
        tot = totient(n)
        if tot == n-1:
            count += 1
        if n == 100 or n == 1000 or n % 10_000 == 0:
            print(f"\nNumber of primes up to {n:6d} = {count}")
 
