IS_NUMBER = re.compile(r'[0-9]')
TWENTY = 20
wheel_map = {}

def advance(wheel):
    w = wheel_map[wheel]
    if IS_NUMBER.match(w.list[w.position]):
        w.print_the_position()
        w.advance_the_position()
    else:
        wheel_name = w.list[w.position]
        advance(wheel_name)
        w.advance_the_position()

def run():
