class WheelModel:
    def __init__(self, name, *values):
        self.name = name.upper()
        self.list = list(values)
        self.position = 0
        self.end_position = len(self.list) - 1

    def __str__(self):
        return str(self.list)

    def advance_the_position(self):
        if self.position == self.end_position:
            self.position = 0
        else:
            self.position += 1

    def print_the_position(self):
        print(' ', self.list[self.position], end='')

