import hashlib
import random
import string
import MySQLdb
 
class UserManager:
    def __init__(self):
        self.dbConnection = None
 
    def md5(self, aString):
        return hashlib.md5(aString.encode('utf-8')).hexdigest()
 
    def connectDB(self, host, port, db, user, password):
        self.dbConnection = MySQLdb.connect(host, user, password, db, port)
 
    def createUser(self, user, password):
        random.seed()
        salt = ''.join(random.choice(string.ascii_uppercase + string.digits) for _ in range(130))
 
        insert = "INSERT INTO users "
            + "(username, pass_salt, pass_md5) "
            + "VALUES (%s, %s, %s)"
 
        try:
            with self.dbConnection.cursor() as cursor:
                cursor.execute(insert, (user, salt, self.md5(salt + password)))
                self.dbConnection.commit()
 
                return True
        except:
            return False
 
    def authenticateUser(self, user, password):
        pass_md5 = None
        pass_salt = None
        select = "SELECT pass_salt, pass_md5 FROM users WHERE username = %s"
 
        try:
            with self.dbConnection.cursor() as cursor:
                cursor.execute(select, (user,))
                res = cursor.fetchone()
 
                pass_salt = res[0]
                pass_md5 = res[1]
 
                if pass_md5 == self.md5(pass_salt + password):
                    return True
                else:
                    return False
        except:
            return False
 
    def closeConnection(self):
        self.dbConnection.close()
 
    def main(self):
        um = UserManager()
        try:
            um.connectDB("localhost", 3306, "test", "root", "admin")
 
            if um.createUser("johndoe", "test"):
                print("User created")
 
            if um.authenticateUser("johndoe", "test"):
                print("User authenticated")
        except:
            pass
        finally:
            um.closeConnection()
 
if __name__ == "__main__":
    UserManager().main()

#include <stdio.h>
 
unsigned chowla(const unsigned n) {
  unsigned sum = 0;
  for (unsigned i = 2, j; i * i <= n; i ++) if (n % i == 0) sum += i + (i == (j = n / i)? 0 : j);
  return sum;
}
 
int main(int argc, char const *argv[]) {
  unsigned a;
  for (unsigned n = 1; n < 38; n ++) printf("chowla(%u) = %u\n", n, chowla(n));
 
  unsigned n, count = 0, power = 100;
  for (n = 2; n < 10000001; n ++) {
    if (chowla(n) == 0) count ++;
    if (n % power == 0) printf("There is %u primes < %u\n", count, power), power *= 10;
  }
 
  count = 0;
  unsigned limit = 350000000;
  unsigned k = 2, kk = 3, p;
  for ( ; ; ) {
    if ((p = k * kk) > limit) break;
    if (chowla(p) == p - 1) {
      printf("%d is a perfect number\n", p);
      count ++;
    }
    k = kk + 1; kk += k;
  }
  printf("There are %u perfect numbers < %u\n", count, limit);
  return 0;
}

import math
 
def is_weird(n):
    proper_divisors = get_proper_divisors(n)
    return is_abundant(proper_divisors, n) and not is_semi_perfect(proper_divisors, n)
 
def is_abundant(divisors, n):
    divisor_sum = sum(divisors)
    return divisor_sum > n
 
#  Use Dynamic Programming
def is_semi_perfect(divisors, sum):
    size = len(divisors)
 
    #  The value of subset[i][j] will be true if there is a subset of divisors[0..j-1] with sum equal to i 
    subset = [[False for i in range(size+1)] for j in range(sum+1)]
 
    # If sum is 0, then answer is true 
    for i in range(size+1):
        subset[0][i] = True
 
    #  If sum is not 0 and set is empty, then answer is false 
    for i in range(1, sum+1):
        subset[i][0] = False
 
    # Fill the subset table in bottom up manner 
    for i in range(1, sum+1):
        for j in range(1, size+1):
            subset[i][j] = subset[i][j-1]
            test = divisors[j-1]
            if i >= test:
                subset[i][j] = subset[i][j] or subset[i - test][j-1]
 
    return subset[sum][size]
 
def get_proper_divisors(number):
    divisors = []
    sqrt = int(math.sqrt(number))
    for i in range(1, sqrt+1):
        if number % i == 0:
            divisors.append(i)
            div = number // i
            if div!= i and div!= number:
                divisors.append(div)
    return divisors
 
