def mod(m, n):
    result = m % n
    if result < 0:
        result = result + n
    return result
 
def getA004290(n):
    if n == 1:
        return 1
    arr = [[0 for x in range(n)] for x in range(n)]
    arr[0][0] = 1
    arr[0][1] = 1
    m = 0
    while True:
        m = m + 1
        if arr[m - 1][mod(-10 ** m, n)] == 1:
            break
        arr[m][0] = 1
        for k in range(1, n):
            arr[m][k] = max(arr[m - 1][k], arr[m - 1][mod(k - 10 ** m, n)])
    r = 10 ** m
    k = mod(-r, n)
    for j in range(m - 1, 0, -1):
        if arr[j - 1][k] == 0:
            r = r + 10 ** j
            k = mod(k - 10 ** j, n)
    if k == 1:
        r = r + 1
    return r
 
