def numOfRows(board):
    return len(board)
def numOfCols(board):
    return len(board[0])
def boardToString(board):
    # First the top-header
    header ='  '
    for c in range(numOfCols(board)):
        header += str(c) +''
    # Then the side-header + board
    sideboard = []
    for r in range(numOfRows(board)):
        sideboard.append(str(r) +'[' +''.join(board[r]) + ']')
    return header + '\n' + '\n'.join(sideboard)
def flipRow(board, row):
    for c in range(numOfCols(board)):
        board[row][c] = 1 - board[row][c]
def flipCol(board, col):
    for r in range(numOfRows(board)):
        board[r][col] = 1 - board[r][col]
def playFlippingBitsGame(rows, cols):
    rows = rows | 3
    cols = cols | 3
    targetBoard = []
    manipulatedBoard = []
    # Randomly generate two identical boards.
    for r in range(rows):
        targetBoard.append([])
        manipulatedBoard.append([])
        for c in range(cols):
            targetBoard[r].append(str(int(math.floor(math.random() * 2))))
            manipulatedBoard[r].append(targetBoard[r][c])
    # Naive-scramble one of the boards.
    while boardToString(targetBoard) == boardToString(manipulatedBoard):
        scrambles = rows * cols
        while scrambles > 0:
            scrambles -= 1
            if 0 == int(math.floor(math.random() * 2)):
                flipRow(manipulatedBoard, int(math.floor(math.random() * rows)))
            else:
                flipCol(manipulatedBoard, int(math.floor(math.random() * cols)))
    # Get the user to solve.
    alert(
        'Try to match both boards.\n' +
        'Enter `r<num>` or `c<num>` to manipulate a row or col or enter `q` to quit.'
        )
    input = ''
    letter = ''
    num = 0
    moves = 0
    while boardToString(targetBoard)!= boardToString(manipulatedBoard) and input!= 'q':
        input = prompt(
            'Target:\n' + boardToString(targetBoard) +
            '\n\n\n' +
            'Board:\n' + boardToString(manipulatedBoard)
            )
        try:
            letter = input[0]
            num = int(input[1:])
            if letter == 'q':
                break
            if (letter!= 'r' and letter!= 'c') or (letter == 'r' and num >= rows) or (letter == 'c' and num >= cols):
                raise Exception('')
            if letter == 'r':
                flipRow(manipulatedBoard, num)
            else:
                flipCol(manipulatedBoard, num)
            moves += 1
        except Exception:
            alert('Uh-oh, there seems to have been an input error')
    if input == 'q':
        alert('~~ Thanks for playing ~~')
    else:
        alert('Completed in'+ str(moves) +'moves.')

import enum
from typing import Callable
 
class Interval:
    def __init__(self, left_endpoint: float, size: float):
        self.left_endpoint = left_endpoint
        self.right_endpoint = left_endpoint + size
 
    @property
    def left_endpoint(self) -> float:
        return self._left_endpoint
 
    @left_endpoint.setter
    def left_endpoint(self, value: float):
        self._left_endpoint = value
 
    @property
    def right_endpoint(self) -> float:
        return self._right_endpoint
 
    @right_endpoint.setter
    def right_endpoint(self, value: float):
        self._right_endpoint = value
 
    @property
    def size(self) -> float:
        return self.right_endpoint - self.left_endpoint
 
    @property
    def center(self) -> float:
        return (self.left_endpoint + self.right_endpoint) / 2
 
    def subdivide(self, subinterval_count: int) -> list:
        subinterval_size = self.size / subinterval_count
        return [Interval(self.left_endpoint + index * subinterval_size, subinterval_size) for index in range(subinterval_count)]
 
class DefiniteIntegral:
    def __init__(self, integrand: Callable[[float], float], domain: Interval):
        self.integrand = integrand
        self.domain = domain
 
    @property
    def integrand(self) -> Callable[[float], float]:
        return self._integrand
 
    @integrand.setter
    def integrand(self, value: Callable[[float], float]):
        self._integrand = value
 
    @property
    def domain(self) -> Interval:
        return self._domain
 
    @domain.setter
    def domain(self, value: Interval):
        self._domain = value
 
    def sample_integrand(self, approximation_method: 'DefiniteIntegral.ApproximationMethod', subdomain: Interval) -> float:
        if approximation_method == DefiniteIntegral.ApproximationMethod.RectangleLeft:
            return self.integrand(subdomain.left_endpoint)
        elif approximation_method == DefiniteIntegral.ApproximationMethod.RectangleMidpoint:
            return self.integrand(subdomain.center)
        elif approximation_method == DefiniteIntegral.ApproximationMethod.RectangleRight:
            return self.integrand(subdomain.right_endpoint)
        elif approximation_method == DefiniteIntegral.ApproximationMethod.Trapezium:
            return (self.integrand(subdomain.left_endpoint) + self.integrand(subdomain.right_endpoint)) / 2
        elif approximation_method == DefiniteIntegral.ApproximationMethod.Simpson:
            return (self.integrand(subdomain.left_endpoint) + 4 * self.integrand(subdomain.center) + self.integrand(subdomain.right_endpoint)) / 6
        else:
            raise NotImplementedError()
 
    def approximate(self, approximation_method: 'DefiniteIntegral.ApproximationMethod', subdomain_count: int) -> float:
        return self.domain.size * sum(self.sample_integrand(approximation_method, subdomain) for subdomain in self.domain.subdivide(subdomain_count)) / subdomain_count
 
    class ApproximationMethod(enum.Enum):
        RectangleLeft = 1
        RectangleMidpoint = 2
        RectangleRight = 3
        Trapezium = 4
        Simpson = 5
 
def test_approximation_methods(integral: DefiniteIntegral, subdomain_count: int):
    for approximation_method in DefiniteIntegral.ApproximationMethod:
        print(integral.approximate(approximation_method, subdomain_count))
 
if __name__ == '__main__':
    test_approximation_methods(DefiniteIntegral(lambda x: x * x * x, Interval(0, 1)), 10000)
    test_approximation_methods(DefiniteIntegral(lambda x: 1 / x, Interval(1, 99)), 1000)
    test_approximation_methods(DefiniteIntegral(lambda x: x, Interval(0, 5000)), 500000)
    test_approximation_methods(DefiniteIntegral(lambda x: x, Interval(0, 6000)), 6000000)

