import re
import sys

e = re.compile(r"\s+")

def main():
    infile = open(sys.argv[1])
    duplicates = []
    datestamps = set()
    all_ok = 0
    pattern_ok = 0
    for line in infile:
        fields = e.split(line)
        if len(fields) == 49:
            pattern_ok += 1
        else:
            print("Format not ok!")
        if datestamps.add(fields[0]) is None:
            howoften = (len(fields) - 1) // 2
            for n in range(1, howoften):
                if fields[2 * n] >= 1:
                    if n == howoften:
                        all_ok += 1
                        break
    infile.close()
    print("The following %d datestamps were duplicated:" % len(duplicates))
    for datestamp in duplicates:
        print(datestamp)
    print("%d records were complete and ok!" % all_ok)

if __name__ == "__main__":
    main()

