def is_prime(n):
	for i in range(2, n):
		if i * i > n:
			return True
		if n % i == 0:
			return False
	return n > 1
 
def is_safe_prime(n):
	return is_prime(n) and is_prime((n - 1) / 2)
 
def is_unsafe_prime(n):
	return is_prime(n) and not is_prime((n - 1) / 2)
 
def next_prime(n):
	for i in range(n+1, 1000000000):
		if is_prime(i):
			return i
	return 0
 
def main():
	safe = 0
	unsf = 0
	p = 2
 
	print("first 35 safe primes: ", end="")
	while safe < 35:
		if is_safe_prime(p):
			safe += 1
			print(p, end=" ")
		p = next_prime(p)
	print("")
 
	p = 2
 
	print("first 35 unsafe primes: ", end="")
	while unsf < 35:
		if is_unsafe_prime(p):
			unsf += 1
			print(p, end=" ")
		p = next_prime(p)
	print("")
 
	p = 2
	safe = 0
	unsf = 0
 
	while p < 1000000:
		if is_safe_prime(p):
			safe += 1
		else:
			unsf += 1
		p = next_prime(p)
	print("safe primes below 1,000,000: {}".format(safe))
	print("unsafe primes below 1,000,000: {}".format(unsf))
 
	while p < 10000000:
		if is_safe_prime(p):
			safe += 1
		else:
			unsf += 1
		p = next_prime(p)
	print("safe primes below 10,000,000: {}".format(safe))
	print("unsafe primes below 10,000,000: {}".format(unsf))
 
