def fibseries(n):
    fib = [1, 1]
    for i in range(n):
        if i < 2:
            fib.append(fib[i])
        else:
            fib.append(fib[i - 1] + fib[i - 2])
    return fib

def benford(array):
    return [[val, array.count(val) / len(array), math.log10(1 + 1 / val)] for val in range(1, 10)]

print(benford(fibseries(1000)))

def ack(m, n):
    if m == 0:
        return n + 1
    elif n == 0:
        return ack(m - 1, 1)
    else:
        return ack(m - 1, ack(m, n - 1))
 
