import itertools
 
def four_square(low, high, unique, print_):
    count = 0
    if print_:
        print("a b c d e f g")
    for a in range(low, high + 1):
        for b in range(low, high + 1):
            if not_valid(unique, a, b):
                continue
            fp = a + b
            for c in range(low, high + 1):
                if not_valid(unique, c, a, b):
                    continue
                for d in range(low, high + 1):
                    if not_valid(unique, d, a, b, c):
                        continue
                    if fp!= b + c + d:
                        continue
                    for e in range(low, high + 1):
                        if not_valid(unique, e, a, b, c, d):
                            continue
                        for f in range(low, high + 1):
                            if not_valid(unique, f, a, b, c, d, e):
                                continue
                            if fp!= d + e + f:
                                continue
                            for g in range(low, high + 1):
                                if not_valid(unique, g, a, b, c, d, e, f):
                                    continue
                                if fp!= f + g:
                                    continue
                                count += 1
                                if print_:
                                    print(f"{a} {b} {c} {d} {e} {f} {g}")
    if unique:
        print(f"There are {count} unique solutions in [{low}, {high}]")
    else:
        print(f"There are {count} non-unique solutions in [{low}, {high}]")
 
def not_valid(unique, needle, *haystack):
    return unique and needle in haystack
 
if __name__ == "__main__":
    four_square(1, 7, True, True)
    four_square(3, 9, True, True)
    four_square(0, 9, False, False)

from itertools import permutations
 
def partitions(args):
    sum = 0
    for a in args:
        sum += a
    nums = range(1, sum + 1)
    for p in permutations(nums):
        total_index = 0
        parts = []
        for a in args:
            part = []
            cont = True
            for j in range(a):
                for p in part:
                    if p > nums[total_index]:
                        cont = False
                        break
                if cont:
                    part.append(nums[total_index])
                    total_index += 1
            if len(part)!= a:
                break
            parts.append(part)
        if len(parts) == len(args):
            print "(",
            for p in parts:
                print "{ ",
                for e in p:
                    print e,
                print "},",
            print "),"
 
