    partitions(args)

def mcnugget(limit):
    sv = [False] * (limit + 1)
    for s in range(0, limit + 1, 6):
        for n in range(s, limit + 1, 9):
            for t in range(n, limit + 1, 20):
                sv[t] = True
    for i in range(limit, -1, -1):
        if not sv[i]:
            print("Maximum non-McNuggets number is", i)
            return
 
