def permute(input):
    if len(input) == 1:
        return [input]
    perms = []
    to_insert = input[0]
    for perm in permute(input[1:]):
        for i in range(len(perm) + 1):
            new_perm = perm[:i] + [to_insert] + perm[i:]
            perms.append(new_perm)
    return perms
 
def derange(input):
    if not input:
        return [input]
    return [perm for perm in permute(input) if all(i!= perm[i] for i in range(len(perm)))]
 
def sub_factorial(n):
    if n == 0:
        return 1
    if n == 1:
        return 0
    return (n - 1) * (sub_factorial(n - 1) + sub_factorial(n - 2))
 
if __name__ == '__main__':
    input = ['a', 'b', 'c', 'd']
 
    derangements = derange(input)
    print("There are {} derangements of {}, namely:\n".format(len(derangements), input))
    for derangement in derangements:
        print(derangement)
 
    print("\nN  Counted   Calculated")
    print("-  -------   ----------")
    for n in range(10):
        counted = len(derange(list(range(n))))
        print("{:d}  {:9d} {:9d}".format(n, counted, sub_factorial(n)))
    print("\n!20 = {}".format(sub_factorial(20)))

import itertools
 
def top_floor(permutation, person):
    return permutation.endswith(person)
 
def bottom_floor(permutation, person):
    return permutation.startswith(person)
 
def lives_above(permutation, upper_person, lower_person):
    return permutation.index(upper_person) > permutation.index(lower_person)
 
def adjacent(permutation, person1, person2):
    return abs(permutation.index(person1) - permutation.index(person2)) == 1
 
def is_possible(s):
    if top_floor(s, "B"):
        return False
    if bottom_floor(s, "C"):
        return False
    if top_floor(s, "F") or bottom_floor(s, "F"):
        return False
    if not lives_above(s, "M", "C"):
        return False
    if adjacent(s, "S", "F"):
        return False
    return not adjacent(s, "F", "C")
 
def main():
    set = set()
    for permutation in itertools.permutations("BCFMS"):
        if is_possible(permutation):
            set.add(permutation)
    for permutation in set:
        print("Possible arrangement: " + "".join(permutation))
 
if __name__ == "__main__":
    main()

import re
import os
 
def read_tests(path):
    with open(path, 'r') as f:
        return f.read().splitlines()
 
def read_rules(path):
    with open(path, 'r') as f:
        return [line.splitlines() for line in f.read().split('\n\n')]
 
def main():
    rules = read_rules('markov_rules.txt')
    tests = read_tests('markov_tests.txt')
 
    pattern = re.compile(r'^([^#]*?)\s+->\s+(\.?)(.*)')
 
    for i in range(len(tests)):
        orig_test = tests[i]
 
        captures = []
        for rule in rules[i]:
            m = pattern.match(rule)
            if m:
                captures.append(m.groups())
 
        test = orig_test
        copy = test
        for j in range(len(captures)):
            c = captures[j]
            test = test.replace(c[0], c[2])
            if c[1] == '.':
                break
            if test!= copy:
                j = -1
                copy = test
 
        print(orig_test)
        print(test)
        print()
 
if __name__ == '__main__':
    main()

