class Kelvin:
    def __init__(self, degrees):
        self.degrees = degrees
 
    def toCelsius(self):
        return self.degrees - 273.15
 
    def toFahreneit(self):
        return (self.degrees - 273.15) * 1.8 + 32.0
 
    def toRankine(self):
        return (self.degrees - 273.15) * 1.8 + 32.0 + 459.67
 
