class ElementaryCA:
    def __init__(self, rule):
        self.rule = rule
        self.state = 1
    def next(self):
        next_state = 0
        state = self.state
        for i in range(64):
            next_state |= (((self.rule)>>(7 & (state.rotate_left(1).rotate_right(i)))) & 1)<<i
        self.state = next_state
        return self.state
 
def rep_u64(val):
    out = ""
    for i in range(64):
        if 1<<i & val!= 0:
            out = out + "\u2588"
        else:
            out = out + "-"
    return out
 
