def toInt(c):
    return ord(c) - ord('0')
 
def confirm(id):
    is_odd_dgt = True
    s = 0
    for c in reversed(id):
        k = toInt(c)
        if is_odd_dgt:
            s += k
        else:
            s += (k!= 9) and (2*k)%9 or 9
        is_odd_dgt = not is_odd_dgt
    return 0 == s%10
 
