from __future__ import division
import math
 
MAXITER = 151
 
def minkowski(x):
    if x > 1 or x < 0:
        return math.floor(x) + minkowski(x - math.floor(x))
    p = int(x)
    q = 1
    r = p + 1
    s = 1
    d = 1.0
    y = p
    while True:
        d /= 2
        if y + d == y:
            break
        m = p + r
        if m < 0 or p < 0:
            break
        n = q + s
        if n < 0:
            break
        if x < m / n:
            r = m
            s = n
        else:
            y += d
            p = m
            q = n
    return y + d
 
def minkowskiInv(x):
    if x > 1 or x < 0:
        return math.floor(x) + minkowskiInv(x - math.floor(x))
    if x == 1 or x == 0:
        return x
    contFrac = [0]
    curr = 0
    count = 1
    i = 0
    while True:
        x *= 2
        if curr == 0:
            if x < 1:
                count += 1
            else:
                i += 1
                contFrac.append(count)
                count = 1
                curr = 1
                x -= 1
        else:
            if x > 1:
                count += 1
                x -= 1
            else:
                i += 1
                contFrac.append(count)
                count = 1
                curr = 0
        if x == math.floor(x):
            contFrac.append(count)
            break
        if i == MAXITER:
            break
    ret = 1.0 / contFrac[i]
    for j in range(i - 1, -1, -1):
        ret = contFrac[j] + 1.0 / ret
    return 1.0 / ret
 
if __name__ == "__main__":
    print("%19.16f %19.16f" % (minkowski(0.5 * (1 + math.sqrt(5))), 5.0 / 3.0))
    print("%19.16f %19.16f" % (minkowskiInv(-5.0 / 9.0), (math.sqrt(13) - 7) / 6))
    print("%19.16f %19.16f" % (minkowski(minkowskiInv(0.718281828)),
        minkowskiInv(minkowski(0.1213141516171819))))

Symbols = { 1:'I', 5:'V', 10:'X', 50:'L', 100:'C', 500:'D', 1000:'M' }
Subtractors = [ [1000, 100], [500, 100], [100, 10], [50, 10], [10, 1], [5, 1], [1, 0] ]
 
def roman(num):
    if num in Symbols:
        return Symbols[num]
    for cutPoint, subtractor in Subtractors:
        if num > cutPoint:
            return roman(cutPoint) + roman(num - cutPoint)
        if num >= cutPoint - subtractor and num < cutPoint:
            return roman(subtractor) + roman(num + subtractor)
 
for i in [1990, 2008, 1666]:
    print "%4d => %s" % (i, roman(i))

import math
 
MAX = 120
 
def extract_prime_factor(num):
    i = 0
    if is_prime(num):
        return None
    while True:
        prime = primes[i]
        if num % prime == 0:
            return (prime, num // prime)
        i += 1
 
def factorize(num):
    factorized = []
    rest = num
    while True:
        prime_factor = extract_prime_factor(rest)
        if prime_factor is None:
            break
        factorized.append(prime_factor[0])
        rest = prime_factor[1]
    factorized.append(rest)
    return factorized
 
def is_prime(num):
    if num == 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(num)) + 1, 2):
        if num % i == 0:
            return False
    return True
 
primes = [2]
for i in range(3, MAX + 1, 2):
    if is_prime(i):
        primes.append(i)
 
output = []
for num in range(4, MAX + 1):
    if is_prime(len(factorize(num))):
        output.append(num)
print(output)

def aks_coefficients(k):
    coefficients = [0] * (k + 1)
    coefficients[0] = 1
    for i in range(1, k + 1):
        coefficients[i] = -sum(coefficients[j] for j in range(i))
    return coefficients
 
def is_prime(p):
    if p < 2:
        return False
    c = aks_coefficients(p)
    return all(c[i] % p == 0 for i in range(1, p // 2 + 1))
 
if __name__ == '__main__':
    for i in range(8):
        print(i, aks_coefficients(i))
    print(' '.join(str(i) for i in range(1, 51) if is_prime(i)))

import math
import struct
 
def hue_to_rgb(hue, sat):
	x = 0
	c = 255 * sat
	hue /= 60
	x = (1 - abs(math.fmod(hue, 2) - 1)) * 255
 
	if hue == 0:
		return (c, x, 0)
	elif hue == 1:
		return (x, c, 0)
	elif hue == 2:
		return (0, c, x)
	elif hue == 3:
		return (0, x, c)
	elif hue == 4:
		return (x, 0, c)
	elif hue == 5:
		return (c, 0, x)
 
size = 512
colors = [hue_to_rgb(i * 240. / size, i * 1. / size) for i in range(size)]
pix = [colors[(i ^ j)] for i in range(size) for j in range(size)]
 
