	f.write("P6\n%d %d\n255\n" % (size, size))
	f.write(struct.pack("%dB" % (size * size * 3), *sum(pix, ())))

from math import sqrt
 
class Ulam:
    def generate(n, i=1, c='*'):
        assert n > 1
        s = [['' for _ in range(n)] for _ in range(n)]
        dir = Direction.RIGHT
        y = n // 2
        x = y - 1 if n % 2 == 0 else y
        for j in range(i, n * n + i):
            s[y][x] = '%4d' % j if is_prime(j) and c.isdigit() else' %s'% c if is_prime(j) else'---'
 
            if dir == Direction.RIGHT and x <= n - 1 and not s[y - 1][x] and j > i:
                dir = Direction.UP
            elif dir == Direction.UP and not s[y][x - 1]:
                dir = Direction.LEFT
            elif dir == Direction.LEFT and (x == 0 or not s[y + 1][x]):
                dir = Direction.DOWN
            elif dir == Direction.DOWN and not s[y][x + 1]:
                dir = Direction.RIGHT
 
            if dir == Direction.RIGHT:
                x += 1
            elif dir == Direction.UP:
                y -= 1
            elif dir == Direction.LEFT:
                x -= 1
            elif dir == Direction.DOWN:
                y += 1
 
        for row in s:
            print('[' + ''.join(row) + ']')
        print()
 
    class Direction:
        RIGHT, UP, LEFT, DOWN = range(4)
 
    def is_prime(a):
        if a == 2:
            return True
        elif a <= 1 or a % 2 == 0:
            return False
        else:
            max = int(sqrt(a))
            for n in range(3, max + 1, 2):
                if a % n == 0:
                    return False
            return True
 
if __name__ == '__main__':
    Ulam.generate(9, c='0')
    Ulam.generate(9)

# ------------------- ASCII TABLE -------------------
#
# asciiTable :: String
def asciiTable():
    return "\n".join(
        map(
            lambda xs: " ".join(
                map(
                    lambda x: justifyLeft(12)(" ")(x),
                    xs
                )
            ),
            transpose(
                chunksOf(16)(
                    list(
                        map(
                            asciiEntry,
                            enumFromTo(32)(127)
                        )
                    )
                )
            )
        )
    )
#
# asciiEntry :: Int -> String
def asciiEntry(n):
    k = asciiName(n)
    return "" if "" == k else f"{justifyRight(4)(" ")(str(n))} : {k}"
#
# asciiName :: Int -> String
def asciiName(n):
    return "" if 32 > n or 127 < n else "Spc" if 32 == n else "Del" if 127 == n else chr(n)
#
# ---------------- GENERIC FUNCTIONS ----------------
#
# chr :: Int -> Char
def chr(x):
    # The character at unix code-point x.
    return chr(x)
#
# chunksOf :: Int -> [a] -> [[a]]
def chunksOf(n):
    def go(xs):
        chunk = xs[0:n]
        return [] if 0 >= len(chunk) else [chunk] + go(xs[n:])
    return go
#
# enumFromTo :: Int -> Int -> [Int]
def enumFromTo(m):
    def go(n):
        return list(range(m, 1 + n))
    return go
#
# justifyLeft :: Int -> Char -> String -> String
def justifyLeft(n):
    # The string s, followed by enough padding (with
    # the character c) to reach the string length n.
    def go(c):
        def go(s):
            return s if n > len(s) else s.rjust(n, c)
        return go
    return go
#
# justifyRight :: Int -> Char -> String -> String
def justifyRight(n):
    # The string s, preceded by enough padding (with
    # the character c) to reach the string length n.
    def go(c):
        def go(s):
            return s if n > len(s) else s.ljust(n, c)
        return go
    return go
#
# transpose :: [[a]] -> [[a]]
def transpose(rows):
    # The columns of the input transposed
    # into new rows.
    # This version assumes input rows of even length.
    return [] if 0 >= len(rows) else list(
        map(
            lambda i: list(
                map(
                    lambda v: v[i],
                    rows
                )
            ),
            range(0, len(rows[0]))
        )
    )
#
# MAIN ---
print(asciiTable())

class ShortestCommonSupersequence:
    def __init__(self):
        self.cache = {}

    def scs(self, x, y):
        if len(x) == 0:
            return y
        if len(y) == 0:
            return x

        if (x, y) in self.cache:
            return self.cache[(x, y)]

        if x[0] == y[0]:
            return self.cache[(x, y)] = x[0] + self.scs(x[1:], y[1:])

        xr = self.scs(x[1:], y)
        yr = self.scs(x, y[1:])
        if len(yr) <= len(xr):
            return self.cache[(x, y)] = y[0] + yr
        else:
            return self.cache[(x, y)] = x[0] + xr

if __name__ == "__main__":
    scs = ShortestCommonSupersequence()
    print(scs.scs("abcbdab", "bdcaba"))

