def perms(n):
    p = [-i for i in range(1, n+1)]
    s = 1
    while True:
        yield [abs(i) for i in p[1:]], s
        k = 0
        for i in range(2, n+1):
            if p[i-1] < 0 and abs(p[i-1]) > abs(p[i-2]) and abs(p[i-1]) > abs(p[k-1]):
                k = i
        for i in range(1, n):
            if p[i-1] > 0 and abs(p[i-1]) > abs(p[i]) and abs(p[i-1]) > abs(p[k-1]):
                k = i
        if k == 0:
            break
        for i in range(1, n+1):
            if abs(p[i-1]) > abs(p[k-1]):
                p[i-1] *= -1
        i = k + (1 if p[k-1] < 0 else -1)
        p[k-1], p[i-1] = p[i-1], p[k-1]
        s = -s
 
for i in range(3, 5):
    for perm, sign in perms(i):
        print("Perm: {}  Sign: {}".format(perm, sign))
    print()

import math
 
def divisors(n):
    res = [1, n]
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            res.extend([i, n // i])
    return sorted(set(res))
 
def zumkeller(n):
    divs = divisors(n)
    sum_divs = sum(divs)
    if sum_divs % 2!= 0 or sum_divs < 2 * n:
        return False
    half = sum_divs // 2
    max_combi_size = len(divs) // 2
    for combi_size in range(1, max_combi_size + 1):
        for combi in combinations(divs, combi_size):
            if sum(combi) == half:
                return True
    return False
 
def combinations(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    if r > n:
        return
    indices = list(range(r))
    yield tuple(pool[i] for i in indices)
    while True:
        for i in reversed(range(r)):
            if indices[i]!= i + n - r:
                break
        else:
            return
        indices[i] += 1
        for j in range(i+1, r):
            indices[j] = indices[j-1] + 1
        yield tuple(pool[i] for i in indices)
 
def p_enum(enum, cols = 10, col_width = 8):
    for i, n in enumerate(enum):
        print(f"{n:>{col_width}}", end="")
        if (i + 1) % cols == 0:
            print()
 
print(f"{n=220} Zumkeller numbers:")
p_enum(i for i in range(1, 1000000) if zumkeller(i), 14, 6)
 
print(f"\n{n=40} odd Zumkeller numbers:")
p_enum(i for i in range(1, 1000000, 2) if zumkeller(i), 14, 6)
 
print(f"\n{n=40} odd Zumkeller numbers not ending with 5:")
p_enum(i for i in range(1, 1000000, 2) if i % 5 > 0 and zumkeller(i), 14, 6)

import math
import collections
 
def generate_primes(limit):
    sieve = [True] * (limit >> 1)
    for p in range(3, limit, 2):
        if sieve[p >> 1]:
            for q in range(p * p, limit, p << 1):
                sieve[q >> 1] = False
    primes = [2]
    for i in range(1, len(sieve)):
        if sieve[i]:
            primes.append((i << 1) + 1)
    return primes
 
class LegendrePrimeCounter:
    def __init__(self, limit):
        self.primes = generate_primes(int(math.sqrt(limit)))
        self.phi_cache = collections.defaultdict(dict)
    def prime_count(self, n):
        if n < 2:
            return 0
        a = self.prime_count(int(math.sqrt(n)))
        return self.phi(n, a) + a - 1
    def phi(self, x, a):
        if a == 0:
            return x
        try:
            return self.phi_cache[x][a]
        except KeyError:
            result = self.phi(x, a - 1) - self.phi(x // self.primes[a - 1], a - 1)
            self.phi_cache[x][a] = result
            return result
 
if __name__ == '__main__':
    counter = LegendrePrimeCounter(1000000000)
    for i in range(10):
        n = 10 ** i
        print('10^{} {}'.format(i, counter.prime_count(n)))

