from itertools import permutations
from math import factorial
 
def dList(n, sp):
    start = sp - 1  # use 0 basing
 
    a = list(range(n))
    a[start], a[0] = a[0], a[start]
    a[1:] = sorted(a[1:])
 
    first = a[1]
    # recursive closure permutes a[1:]
    def recurse(last):
        if last == first:
            # bottom of recursion. you get here once for each permutation.
            # test if permutation is deranged
            for jv in enumerate(a[1:], 1):
                if jv[0] == jv[1]:
                    return  # no, ignore it
            # yes, save a copy with 1 based indexing
            b = [x + 1 for x in a]
            r.append(b)
            return
        for i in range(last, 0, -1):
            a[i], a[last] = a[last], a[i]
            recurse(last - 1)
            a[i], a[last] = a[last], a[i]
    r = []
    recurse(n - 1)
    return r
 
def reducedLatinSquares(n, echo):
    if n <= 0:
        if echo:
            print("[]\n")
        return 0
    elif n == 1:
        if echo:
            print("[1]\n")
        return 1
 
    rlatin = [[j for j in range(n)] for i in range(n)]
    # first row
    for j in range(n):
        rlatin[0][j] = j + 1
 
    count = 0
    def recurse(i):
        nonlocal count
        rows = dList(n, i)
 
        for r in range(len(rows)):
            rlatin[i - 1] = rows[r]
            for k in range(i - 1):
                for j in range(1, n):
                    if rlatin[k][j] == rlatin[i - 1][j]:
                        if r < len(rows) - 1:
                            continue
                        if i > 2:
                            return
            if i < n:
                recurse(i + 1)
            else:
                count += 1
                if echo:
                    printSquare(rlatin)
    # remaining rows
    recurse(2)
    return count
 
def printSquare(latin):
    for row in latin:
        print(row)
    print()
 
def factorial(n):
    if n == 0:
        return 1
    prod = 1
    for i in range(2, n + 1):
        prod *= i
    return prod
 
if __name__ == "__main__":
    print("The four reduced latin squares of order 4 are:\n")
    reducedLatinSquares(4, True)
 
    print("The size of the set of reduced latin squares for the following orders")
    print("and hence the total number of latin squares of these orders are:\n")
    for n in range(1, 7):
        size = reducedLatinSquares(n, False)
        f = factorial(n - 1)
        f *= f * n * size
        print("Order {0}: Size {1:4d} x {2} x {3} => Total {4}".format(n, size, n, n - 1, f))

