import java.util.Arrays;
import java.util.List;

def ordered(first, second):
    if len(first) == 0:
        return True
    if len(second) == 0:
        return False
    if first[0] == second[0]:
        return ordered(first[1:], second[1:])
    return first[0] < second[0]

def ordered(first, second):
    i = 0
    while i < len(first) and i < len(second):
        cmp = first[i].compareTo(second[i])
        if cmp == 0:
            continue
        if cmp < 0:
            return True
        return False
    return i == len(first)

def ordered2(first, second):
    i = 0
    while i < len(first) and i < len(second):
        if first[i] == second[i]:
            continue
        if first[i] < second[i]:
            return True
        return False
    return i == len(first)

