def jort_sort(array):
    # sort the array
    sorted_array = array.copy()
    sorted_array.sort()
 
    # compare to see if it was originally sorted
    for i in range(len(array)):
        if array[i]!= sorted_array[i]:
            return False
 
    return True

# version 1.1.2
 
best = [0] * 32
 
def trySwaps(deck, f, d, n):
    if d > best[n]:
        best[n] = d
    for i in range(n - 1, -1, -1):
        if deck[i] == -1 or deck[i] == i:
            break
        if d + best[i] <= best[n]:
            return
    deck2 = deck[:]
    for i in range(1, n):
        k = 1 << i
        if deck2[i] == -1:
            if (f & k)!= 0:
                continue
        elif deck2[i]!= i:
            continue
        deck2[0] = i
        for j in range(i - 1, -1, -1):
            deck2[i - j] = deck[j]
        trySwaps(deck2, f | k, d + 1, n)
 
def topswops(n):
    assert n > 0 and n < len(best)
    best[n] = 0
    deck0 = [-1] * (n + 1)
    for i in range(1, n):
        deck0[i] = -1
    trySwaps(deck0, 1, 0, n)
    return best[n]
 
for i in range(1, 11):
    print("%2d : %d" % (i, topswops(i)))

