    def __init__(self):
        self.field = [[0] * SIZE for _ in range(SIZE)]
 
    def available(self, p):
        return 0 <= p.x < SIZE and 0 <= p.y < SIZE and self.field[p.x][p.y] == 0
 
    # calculate the number of possible moves
    def count_degree(self, p):
        count = 0
        for dx, dy in MOVES:
            next = p.mov(dx, dy)
            if self.available(next):
                count += 1
        return count
 
    def __str__(self):
        return '\n'.join(' '.join(map(str, row)) for row in self.field)
 
def knights_tour(x, y):
    board = Board()
    p = Point(x, y)
    step = 1
    board.field[p.x][p.y] = step
    step += 1
 
    while step <= SIZE * SIZE:
        # choose next square by Warnsdorf's rule
        candidates = []
        for dx, dy in MOVES:
            adj = p.mov(dx, dy)
            if board.available(adj):
                degree = board.count_degree(adj)
                candidates.append((degree, adj))
        # move to next square
        if candidates:
            _, p = min(candidates)
        else:
            return None
        board.field[p.x][p.y] = step
        step += 1
    return board
 
if __name__ == '__main__':
    x, y = 3, 1
    print('Board size:', SIZE)
    print('Starting position: ({}, {})'.format(x, y))
    board = knights_tour(x, y)
    if board:
        print(board)
    else:
        print('Fail!')

class PancakeSort:
    def __init__(self, numbers):
        self.heap = numbers
        self.sort(len(numbers), 1)

    def __str__(self):
        return''.join(map(str, self.heap))

    def flip(self, n):
        for i in range(n // 2):
            self.heap[i], self.heap[n - i] = self.heap[n - i], self.heap[i]
        print('flip(0..{}): {}'.format(n, self))

    def minmax(self, n):
        xm, xM = self.heap[0], self.heap[0]
        posm, posM = 0, 0
        for i in range(1, n):
            if self.heap[i] < xm:
                xm, posm = self.heap[i], i
            elif self.heap[i] > xM:
                xM, posM = self.heap[i], i
        return posm, posM

    def sort(self, n, dir):
        if n == 0:
            return
        mM = self.minmax(n)
        bestXPos, altXPos = mM[dir], mM[1 - dir]
        flipped = False
        if bestXPos == n - 1:
            n -= 1
        elif bestXPos == 0:
            self.flip(n - 1)
            n -= 1
        elif altXPos == n - 1:
            dir = 1 - dir
            n -= 1
            flipped = True
        else:
            self.flip(bestXPos)
        self.sort(n, dir)
        if flipped:
            self.flip(n)

if __name__ == '__main__':
    numbers = list(map(int, input().split()))
    pancakes = PancakeSort(numbers)
    print(pancakes)

