class Caesar:
    def encrypt(self, s, key):
        offset = key % 26
        if offset == 0:
            return s
        d = None
        chars = []
        for index, c in enumerate(s):
            if c in 'A'..'Z':
                d = c + offset
                if d > 'Z':
                    d -= 26
            elif c in 'a'..'z':
                d = c + offset
                if d > 'z':
                    d -= 26
            else:
                d = c
            chars.append(d)
        return ''.join(chars)
 
    def decrypt(self, s, key):
        return self.encrypt(s, 26 - key)
 
