def mean_stddev(numbers):
    if not numbers:
        return 0.0, 0.0
    n = len(numbers)
    sx = sum(numbers)
    sxx = sum(x * x for x in numbers)
    return sx / n, sqrt((n * sxx - sx * sx) / n)
 
def replicate(n, s):
    return ''.join(s for _ in range(n + 1))
 
def show_histogram01(numbers):
    max_width = 50
    bins = [0] * 10
    for x in numbers:
        bins[int(x * len(bins))] += 1
    max_freq = max(bins)
    for i, freq in enumerate(bins):
        print('{:3.1f}: {}'.format(i / len(bins), replicate(int(freq / max_freq * max_width), '*')))
 
def main():
    data = [random() for _ in range(100_000)]
    res = mean_stddev(data)
    print('Mean: {:8.6f}, SD: {:8.6f}'.format(*res))
    show_histogram01(data)
 
if __name__ == '__main__':
    main()

