def vanEck(firstIndex, lastIndex):
    vanEckMap = {}
    last = 0
    if firstIndex == 1:
        print("VanEck[1] = 0")
    for n in range(2, lastIndex + 1):
        vanEck = 0 if not last in vanEckMap else n - vanEckMap[last]
        vanEckMap[last] = n
        last = vanEck
        if n >= firstIndex:
            print("VanEck[{}] = {}".format(n, vanEck))

