def zigzagMatrix(n):
    result = [[0] * n for _ in range(n)]
    down = False
    count = 0
    for col in range(n):
        if down:
            for row in range(col + 1):
                result[row][col - row] = count
                count += 1
        else:
            for row in range(col, -1, -1):
                result[row][col - row] = count
                count += 1
        down = not down
    for row in range(1, n):
        if down:
            for col in range(n - 1, row - 1, -1):
                result[row + n - 1 - col][col] = count
                count += 1
        else:
            for col in range(row, n):
                result[row + n - 1 - col][col] = count
                count += 1
        down = not down
    return result
 
def printMatrix(m):
    for i in range(len(m)):
        for j in range(len(m)):
            print("%2d " % m[i][j], end="")
        print()
    print()
 
