def run_game(num_of_cards, minimum_number_of_sets):
    print(f"\nGAME: # of cards: {num_of_cards} # of sets: {minimum_number_of_sets}")
 
    # generate the deck with 81 unique cards
    deck = []
    for a in range(3):
        for b in range(3):
            for c in range(3):
                for d in range(3):
                    deck.append([a, b, c, d])
 
    # closure to return true if the three attributes are the same, or each of them is different
    def valid_attribute(a, b, c):
        return a == b and b == c or (a!= b and b!= c and a!= c)
 
    # closure to test all attributes, each of them should be true to have a valid set
    def valid_set(t):
        for attr in range(num_attributes):
            if not valid_attribute(t[0][attr], t[1][attr], t[2][attr]):
                return False
        return True
 
    while True:
        # select the required # of cards from the deck randomly
        selected_cards = [deck[idx] for idx in get_random_card_indexes(num_of_cards)]
 
        # generate all combinations, and filter/keep only which are valid sets
        valid_sets = [triplet for triplet in combinations(selected_cards, 3) if valid_set(triplet)]
 
        # if the # of the sets is matching the requirement, print it and finish
        if len(valid_sets) == minimum_number_of_sets:
            print("SELECTED CARDS:")
            for card in selected_cards:
                print(f"card: {', '.join(attributes[attr][card[attr]] for attr in range(num_attributes))}")
 
            print("Sets:")
            for triplet in valid_sets:
                print(f"Set: {' | '.join(', '.join(attributes[attr][card[attr]] for attr in range(num_attributes)) for card in triplet)}")
 
            break
 
        #otherwise generate again
 
