def patienceSort(arr):
    if len(arr) < 2:
        return
    piles = []
    for el in arr:
        for pile in piles:
            if pile[-1] > el:
                pile.append(el)
                continue
        piles.append([el])
 
    for i in range(len(arr)):
        min = piles[0][-1]
        minPileIndex = 0
        for j in range(1, len(piles)):
            if piles[j][-1] < min:
                min = piles[j][-1]
                minPileIndex = j
        arr[i] = min
        minPile = piles[minPileIndex]
        minPile.pop()
        if len(minPile) == 0:
            piles.pop(minPileIndex)
 
