def linear_combo(c: List[int]) -> str:
    def format_coeff(n: int) -> str:
        if n == 1:
            return ""
        return f"{n}*"
    def format_term(i: int, n: int) -> str:
        if n == 0:
            return ""
        if n < 0:
            return f" - {format_coeff(-n)}e({i})"
        return f" + {format_coeff(n)}e({i})"
    return reduce(add, map(lambda t: format_term(t[0], t[1]), enumerate(c, 1)), "")
 
