from collections import defaultdict
 
def print_colony(col, width, height):
    for y in range(height):
        for x in range(width):
            print("O" if (x,y) in col else ".", end=" ")
        print()
 
def neighbours(cell):
    x, y = cell
    return [
        (x-1,y-1), (x,y-1), (x+1,y-1),
        (x-1,y),            (x+1,y),
        (x-1,y+1), (x,y+1), (x+1,y+1),
    ]
 
def neighbour_counts(col):
    ncnts = defaultdict(int)
    for cell in col:
        for n in neighbours(cell):
            ncnts[n] += 1
    return ncnts
 
def generation(col):
    return {
        cell for cell, cnt in neighbour_counts(col).items()
        if cnt == 3 or (cnt == 2 and cell in col)
    }
 
def life(init, iters, width, height):
    col = set(init)
    for i in range(iters+1):
        print("({})".format(i))
        if i!= 0:
            col = generation(col)
        print_colony(col, width, height)
 
