from math import sqrt
from itertools import count, islice
 
def is_prime(n):
    return n > 1 and all(n%i for i in islice(count(2), int(sqrt(n)-1)))
 
def prime_decomp(n):
    if n < 2:
        return None
    result = []
    while n % 2 == 0:
        n //= 2
        result.append(2)
    if n!= 1:
        for i in range(3, int(sqrt(n))+1, 2):
            if is_prime(i):
                while n % i == 0:
                    n //= i
                    result.append(i)
    result.append(n)
    return result
 
def is_semi(n):
    decomp = prime_decomp(n)
