from typing import List

def strandSort(lst: List[T]) -> List[T]:
    if len(lst) <= 1:
        return lst
    result = []
    sorted = []
    while lst:
        sorted.append(lst.pop(0))
        for i in range(len(lst)):
            if sorted[-1] <= lst[i]:
                sorted.append(lst.pop(i))
                i -= 1
        result.extend(sorted)
        sorted = []
    return result

