            print('%2i: %s%s' % (i,''*(lines - i), c.translate(str.maketrans('01', '.#'))))

def count_divisors(n):
    count = 0
    i = 1
    k = 2
    if n % 2 == 0:
        k = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
            j = n // i
            if j!= i:
                count += 1
        i += k
    return count
 
