            print()
    i += 1

import random
import time
from enum import Enum
 
class Summer(Enum):
    MAPPING = 1
    SEQUENCING = 2
    FOLDING = 3
    FOR_LOOP = 4
 
    def sum(self, values):
        if self == Summer.MAPPING:
            return sum(map(lambda x: x * x, values))
        elif self == Summer.SEQUENCING:
            return sum(map(lambda x: x * x, values))
        elif self == Summer.FOLDING:
            return reduce(lambda acc, x: acc + x * x, values, 0)
        elif self == Summer.FOR_LOOP:
            acc = 0.0
            for v in values:
                acc += v * v
            return acc
        else:
            raise ValueError(f"Unknown summer {self}")
 
def main():
    test_arrays = [
        [],
        [random.random() * 10],
        [random.random() * 10 for _ in range(6)],
    ]
    for impl in Summer:
        print(f"Test with {impl.name}:")
        for v in test_arrays:
            print(f"  {v} -> {impl.sum(v)}")
 
    elements = 100_000
    long_array = [random.random() * 10 for _ in range(elements)]
 
    for impl in Summer:
        start = time.time()
        impl.sum(long_array)
        end = time.time()
        print(f"Summing {elements} with {impl.name} takes: {(end - start) * 1000}ms")
 
