import math
 
def computePhi():
    phi = [0] * (max + 1)
    for i in range(1, max + 1):
        phi[i] = i
    for i in range(2, max + 1):
        if phi[i] < i:
            continue
        for j in range(i, max + 1, i):
            phi[j] -= phi[j] / i
    return phi
 
def perfectTotient(n):
    test = 2
    results = []
    for i in range(n):
        phiLoop = test
        sum = 0
        while phiLoop > 1:
            phiLoop = phi[phiLoop]
            sum += phiLoop
        if sum == test:
            results.append(test)
        test += 1
    return results
 
