import random
def biased(n):
    return random.randint(1, n) == 1
def unbiased(n):
    flip1 = biased(n)
    flip2 = biased(n)
    while flip1 == flip2:
        flip1 = biased(n)
        flip2 = biased(n)
    return flip1
