def chunk(n, a):
    return [a[i:i+n] for i in range(0, len(a), n)]
 
def to_rows(seq):
    return chunk(row_length, seq)
 
def pad_to(n):
    def pad(v):
        return str(v).rjust(n,'')
    return pad
 
