from math import sqrt
 
def getPrimeFactors(n):
    factors = []
    if n < 2: return factors
    if n.is_probable_prime(20):
        factors.append(n)
        return factors
    factor = 2
    while True:
        if n % factor == 0:
            factors.append(factor)
            n //= factor
            if n == 1: return factors
            if n.is_probable_prime(20): factor = n
        else:
            if factor >= 3: factor += 2
            else: factor = 3
 
