import itertools
import math
 
def is_prime(n):
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True
 
for n in range(1, 9):
    count = 0
    for p1, p2 in itertools.combinations(filter(is_prime, range(10**n)), 2):
        if p2 - p1 == 2:
            count += 1
    print("Twin primes below 10**{}: {}".format(n, count))

import math
 
def WuDrawLine(x0, y0, x1, y1, plot):
    def ipart(x):
        return int(math.floor(x))
    def round(x):
        return int(math.round(x))
    def fpart(x):
        return x - math.floor(x)
    def rfpart(x):
        return 1 - fpart(x)
 
    steep = abs(y1 - y0) > abs(x1 - x0)
    if steep:
        x0, y0 = y0, x0
        x1, y1 = y1, x1
    if x0 > x1:
        x0, x1 = x1, x0
        y0, y1 = y1, y0
 
    dx = x1 - x0
    dy = y1 - y0
    gradient = (dx == 0) and 1 or dy/dx
 
    xpx11 = round(x0)
    intery = y0 + gradient * (xpx11 - x0)
    xgap = rfpart(x0 + 0.5)
    xpx11 = int(xpx11)
    ypx11 = ipart(intery)
    if steep:
        plot(ypx11,     xpx11, rfpart(intery) * xgap)
        plot(ypx11 + 1, xpx11,  fpart(intery) * xgap)
    else:
        plot(xpx11, ypx11,    rfpart(intery) * xgap)
        plot(xpx11, ypx11 + 1, fpart(intery) * xgap)
    intery += gradient
 
    xpx12 = round(x1)
    intery = y1 + gradient * (xpx12 - x1)
    xgap = rfpart(x1 + 0.5)
    xpx12 = int(xpx12)
    ypx12 = ipart(intery)
    if steep:
        plot(ypx12,     xpx12, rfpart(intery) * xgap)
        plot(ypx12 + 1, xpx12,  fpart(intery) * xgap)
    else:
        plot(xpx12, ypx12,    rfpart(intery) * xgap)
        plot(xpx12, ypx12 + 1, fpart(intery) * xgap)
 
    if steep:
        for x in range(xpx11 + 1, xpx12):
            plot(ipart(intery),     x, rfpart(intery))
            plot(ipart(intery) + 1, x,  fpart(intery))
            intery += gradient
    else:
        for x in range(xpx11 + 1, xpx12):
            plot(x, ipart(intery),     rfpart(intery))
            plot(x, ipart(intery) + 1,  fpart(intery))
            intery += gradient

def cocktail_sort(a):
    len = len(a)
    while True:
        swapped = False
        i = 0
        while i + 1 < len:
            if a[i] > a[i + 1]:
                a[i], a[i + 1] = a[i + 1], a[i]
                swapped = True
            i += 1
        if swapped:
            swapped = False
            i = len - 1
            while i > 0:
                if a[i - 1] > a[i]:
                    a[i - 1], a[i] = a[i], a[i - 1]
                    swapped = True
                i -= 1
        if not swapped:
            break
 
v = [10, 8, 4, 3, 1, 9, 0, 2, 7, 5, 6]
print("before: {}".format(v))
cocktail_sort(v)
print("after:  {}".format(v))

