@cache
def phi(x, a):
    res = 0
    while True:
        if not a or not x:
            return x + res
 
        a -= 1
        res -= phi(x//p[a], a) # partial tail recursion
 
def legpi(n):
    if n < 2: return 0
 
    a = legpi(isqrt(n))
    return phi(n, a) + a - 1
 
