def padovan_r() -> Generator[int, None, None]:
    last = deque([1, 1, 1], 4)
    while True:
        last.append(last[-2] + last[-3])
        yield last.popleft()
 
_p, _s = 1.324717957244746025960908854, 1.0453567932525329623
 
def padovan_f(n: int) -> int:
