    print("\nTable of n vs counted vs calculated derangements")
    for n in range(10):
        print("%2i %-5i %-5i" %
              (n, _iterlen(derangements(n)), subfact(n)))
 
    n = 20
    print("\n!%i = %i" % (n, subfact(n)))

