def odd(n):
    return n and 1 != 0
 
def jacobsthal(n):
    return floor((pow(2,n)+odd(n))/3)
 
def jacobsthal_lucas(n):
    return int(pow(2,n)+pow(-1,n))
 
def jacobsthal_oblong(n):
    return jacobsthal(n)*jacobsthal(n+1)
 
 
